"""Portable palette comparison only. Raster artwork comes unchanged from Aseprite."""
from pathlib import Path
import json,shutil,hashlib,html
ROOT=Path(__file__).resolve().parents[1];LIB=ROOT/'Biblioteca de Arte';REL='Estudos Comparativos/Infante de Ferro - Pele Verde';OUT=LIB/REL;OUT.mkdir(parents=True,exist_ok=True)
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
base='characters/orc-pixellab-05';variant=base+'/source/studies/PaletteVariants/green-skin-v1'
inputs=[('01 - Original','Original',base+'/concepts/concept-selected.png',base+'/source/aseprite/concept-selected.aseprite',base+'/source/studies/Idle/clip.json'),('02 - Pele Verde','Pele verde',variant+'/Concept/concept.png',base+'/source/aseprite/green-skin-v1/source/green-concept.aseprite',variant+'/Idle/clip.json')]
inputs.append(('03 - Verde Mais Escuro','Verde mais escuro',base+'/source/studies/PaletteVariants/green-skin-v2/Concept/concept.png',base+'/source/aseprite/green-skin-v2/source/dark-green-concept.aseprite',base+'/source/studies/PaletteVariants/green-skin-v2/Idle/clip.json'))
inputs.append(('04 - Verde Warcraft','Verde Warcraft · mais escuro',base+'/source/studies/PaletteVariants/green-skin-v3/Concept/concept.png',base+'/source/aseprite/green-skin-v3/source/warcraft-green-concept.aseprite',base+'/source/studies/PaletteVariants/green-skin-v3/Idle/clip.json'))
files=[];data=[]
def copy(src,dst):
 target=OUT/dst;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/src,target);files.append({'file':dst,'source':src,'sha256':hashlib.sha256(target.read_bytes()).hexdigest()});return dst
for folder,title,concept,master,clipPath in inputs:
 clip=read(ROOT/clipPath);frames=[{'png':copy(f['png'],folder+f'/Idle/Quadros/{i:02d}.png'),'durationMs':f['durationMs']} for i,f in enumerate(clip['frames'])]
 item={'title':title,'concept':copy(concept,folder+'/Conceito.png'),'conceptMaster':copy(master,folder+'/Conceito.aseprite'),'master':copy(clip['master'],folder+'/Idle.aseprite'),'frames':frames,'cycleMs':sum(f['durationMs'] for f in frames)};data.append(item)
 (OUT/folder/'Idle/clip.json').write_text(json.dumps(item,ensure_ascii=False,indent=2),encoding='utf-8')
cards=''.join(f'<article><h2>{c["title"]}</h2><h3>Conceito</h3><div class="stage"><img src="{c["concept"]}" alt="Infante de Ferro {c["title"]}"></div><h3>Idle · padrão aprovado de 2,2 s</h3><div class="stage"><canvas id="anim-{i}" width="128" height="128"></canvas></div><p id="frame-{i}"></p><p><a href="{c["conceptMaster"]}">Mestre do conceito</a> · <a href="{c["master"]}">Mestre do Idle</a></p></article>' for i,c in enumerate(data))
# Reuse the already verified generic comparison player (data length is dynamic).
source=(LIB/'Estudos Comparativos/Infante de Ferro - Idle/index.html').read_text(encoding='utf-8')
player='const cache'+source.split(';const cache',1)[1].split('</script>',1)[0]
player=player.replace("querySelectorAll('canvas')","querySelectorAll('canvas,img')")
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Infante de Ferro · estudo de pele verde</title><style>*{box-sizing:border-box}body{margin:24px;background:#15252a;color:#e3ebe8;font:16px/1.5 system-ui}a{color:#dfc18b}.options{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}article{padding:18px;background:#23383d;border:1px solid #5b757a;border-radius:8px}h2{margin:0}h3{font-size:16px;color:#dcc18c}p{color:#bdcfca}.stage{height:280px;display:flex;align-items:center;justify-content:center;overflow:auto;background:repeating-conic-gradient(#2b3f45 0 25%,#3a5259 0 50%) 0/20px 20px}canvas,img{width:256px;height:256px;image-rendering:pixelated;object-fit:contain;flex-shrink:0}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}button,select{font:inherit;color:white;background:#344c54;padding:8px;border:1px solid #6e8a91;border-radius:4px}@media(max-width:850px){.options{grid-template-columns:1fr}}</style><h1>Infante de Ferro · pele verde</h1><p><a href="../../index.html">Voltar à Biblioteca de Arte</a></p><p>Estudo de paleta inspirado nos verdes clássicos dos Orcs de Warcraft: pele verde-folha, sombras verde-escuras e luzes mais quentes. A última opção usa cores de pele amostradas de uma imagem oficial do Orc de Warcraft, selecionando sombras e tons médios para um verde mais escuro. Todas as versões anteriores foram preservadas. Rosto, proporções, armadura e pixels fora da pele preservados. A versão original permanece selecionada.</p><div class="toolbar"><button id="play">Pausar</button><button id="reset">Reiniciar juntos</button><button id="step">Avançar um quadro</button><label>Zoom <select id="zoom"><option value="1">1× nativo</option><option value="2" selected>2×</option><option value="3">3×</option></select></label><label>Velocidade <select id="speed"><option value="1">1× real</option><option value="0.5">0,5×</option></select></label></div><div class="options">CARDS</div><p>Nova paleta aplicada no Aseprite sobre arte herdada do PixelLab. O Idle usa as mesmas cinco poses e os mesmos tempos do padrão fixo; a variante verde aguarda avaliação. Walk e demais artes originais permanecem intactos.</p><script>const data=DATA;PLAYER</script></html>'''.replace('CARDS',cards).replace('DATA',payload).replace('PLAYER',player)
(OUT/'index.html').write_text(page,encoding='utf-8')
(OUT/'catalogo.json').write_text(json.dumps({'date':'2026-10-25','variants':data,'files':files,'selected':False,'artisticApproval':'PENDING_CREATOR_PALETTE'},ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'LEIA-ME.md').write_text('# Infante de Ferro — estudo de pele verde\n\nComparação com conceito e Idle original intactos. Variante de paleta do mesmo indivíduo, não novo personagem. Aplicação seletiva de cores no Aseprite, sem geração nova. As cinco poses e tempos 400/450/500/450/400 ms foram preservados. PNGs e mestres editáveis separados; fontes em catalogo.json. Variante não selecionada para produção. Atualizar com tools/build-infante-green-review.py.\n',encoding='utf-8')
p=ROOT/'docs/ART_LIBRARY_COMPARISONS.json';registry=read(p);registry=[r for r in registry if r['id']!='infante-green-skin-v1'];registry.append({'id':'infante-green-skin-v1','title':'Infante de Ferro · pele verde','path':REL+'/index.html','builder':'tools/build-infante-green-review.py'});p.write_text(json.dumps(registry,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'page':str(OUT/'index.html'),'variants':4,'copiedArtFiles':len(files)},ensure_ascii=False))
